    @asynccontextmanager
    async def reserve(self, policy, requested, *, timeout, allowed_gpu_uuids=None):
        if policy not in {"cpu", "gpu", "auto"} or requested <= 0:
            raise AdmissionError("Invalid resource request", "invalid_input")
        lease = None
        deadline = asyncio.get_running_loop().time() + timeout if timeout is not None else None
        try:
            while lease is None:
                devices = self.eligible(await self.probe()) if policy != "cpu" else []
                if allowed_gpu_uuids is not None:
                    devices = [
                        device
                        for device in devices
                        if device["uuid"] in allowed_gpu_uuids
                    ]
                if policy == "gpu" and not devices:
                    raise AdmissionError(
                        "No permitted GPU with the required execution evidence is available outside the LLM reservation",
                        "backend_unavailable",
                    )
                async with self.condition:
                    ranked = []
                    for device in devices:
                        if any(item.gpu_uuid == device["uuid"] for item in self.leases.values()):
                            continue  # One native workflow at a time on GPU 1.
                        reserved = sum(
                            item.reserved_bytes
                            for item in self.leases.values()
                            if item.gpu_uuid == device["uuid"]
                        )
                        capacity = min(
                            device["free"],
                            max(0, device["total"] - device["llm_reserve"]),
                        )
                        available = (
                            capacity
                            - reserved
                            - self.settings.analytics_gpu_headroom_bytes
                        )
                        ranked.append((available, device))
                    # Prefer the device with more admitted space; UUID breaks ties.
                    ranked.sort(key=lambda item: (-item[0], item[1]["uuid"]))
                    if ranked and ranked[0][0] >= requested:
                        available, device = ranked[0]
                        from .backend_learning.leases import GPULock

                        try:
                            lock = GPULock.acquire(self.settings.backend_data_dir)
                        except OSError as error:
                            raise AdmissionError("The shared GPU 1 lease is unavailable") from error
                        if lock:
                            lease = Lease(str(uuid4()), "gpu", device["uuid"], requested,
                                          available, device["llm_reserve"])
                            self.gpu_locks[lease.id] = lock
                    elif policy == "gpu" and requested > max(
                        device["total"]
                        - device["llm_reserve"]
                        - self.settings.analytics_gpu_headroom_bytes
                        for device in devices
                    ):
                        raise AdmissionError(
                            "This workflow exceeds every permitted GPU's memory admission limit"
                        )
                    if lease is None and policy != "gpu":
                        cpu = [
                            item
                            for item in self.leases.values()
                            if item.device == "cpu"
                        ]
